import { useState } from "react";
import { NavLink, useNavigate } from "react-router-dom";
import {
  LayoutDashboard,
  Users,
  Car,
  Wrench,
  Calendar,
  FileText,
  UserCog,
  Package,
  Sparkles,
  Megaphone,
  Upload,
  LogOut,
  ChevronDown,
  Settings,
  Shield,
  HardHat,
  TrendingUp,
  Building2,
  Check,
  Plus,
  Merge,
  Navigation,
  MessageSquare,
} from "lucide-react";
import { cn } from "@/lib/utils.ts";
import { useQuery, useMutation } from "convex/react";
import { api } from "@/convex/_generated/api.js";
import type { Id } from "@/convex/_generated/dataModel.d.ts";
import { useAuth as useOidcAuth } from "react-oidc-context";
import { Button } from "@/components/ui/button.tsx";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu.tsx";
import { toast } from "sonner";
import LocationSwitcher from "./LocationSwitcher.tsx";
import { useLocationFilter } from "@/hooks/use-location-filter.tsx";
import { NAV_ITEMS, type NavRole } from "@/lib/nav-config.ts";

export default function Sidebar() {
  const { removeUser, user } = useOidcAuth();
  const navigate = useNavigate();
  const currentOrg = useQuery(api.organizations.getCurrentOrg, {});
  const myOrgs = useQuery(api.organizations.getMyOrgs, {});
  const myRole = useQuery(api.admin.getMyRole, {});
  const switchOrg = useMutation(api.organizations.switchOrg);
  const [switching, setSwitching] = useState<string | null>(null);
  const { selectedLocationId } = useLocationFilter();

  // Fetch notification badge counts
  const badges = useQuery(api.notifications.getBadgeCounts, selectedLocationId ? { locationId: selectedLocationId } : {});

  const role = myRole?.role ?? null;
  const hasAdminAccess = myRole?.hasAdminAccess ?? false;

  // Map routes to their badge counts
  const badgeMap: Record<string, number> = {
    "/schedule": badges?.pendingBookings ?? 0,
    "/invoices": badges?.overdueInvoices ?? 0,
    "/jobs": badges?.overdueJobs ?? 0,
    "/parts": badges?.lowStockParts ?? 0,
  };

  // Total alert count for dashboard indicator
  const totalAlerts = Object.values(badgeMap).reduce((sum, n) => sum + n, 0);
  if (totalAlerts > 0) {
    badgeMap["/dashboard"] = totalAlerts;
  }

  const visibleItems = role
    ? NAV_ITEMS.filter((item) => {
        // If member has admin access, show everything admin can see
        if (hasAdminAccess && item.roles.includes("admin")) return true;
        return item.roles.includes(role as NavRole);
      })
    : NAV_ITEMS;

  const handleSwitch = async (orgId: Id<"organizations">) => {
    setSwitching(orgId);
    try {
      await switchOrg({ orgId });
      toast.success("Switched location");
    } catch {
      toast.error("Failed to switch location");
    } finally {
      setSwitching(null);
    }
  };

  const handleSignout = async () => {
    try {
      await removeUser();
      navigate("/");
    } catch {
      toast.error("Failed to sign out");
    }
  };

  return (
    <aside className="hidden md:flex flex-col w-64 border-r border-sidebar-border bg-sidebar h-screen">
      {/* Logo + Org Switcher */}
      <div className="px-5 py-4 border-b border-sidebar-border">
        <h1
          className="text-xl font-bold text-primary tracking-wider"
          style={{ fontFamily: "Rajdhani, sans-serif" }}
        >
          ⚙ Shop Crank
        </h1>
        {currentOrg && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button className="flex items-center gap-1 mt-1 group w-full text-left cursor-pointer">
                <p className="text-xs text-muted-foreground truncate transition-colors flex-1 group-hover:text-foreground">
                  {currentOrg.name}
                </p>
                <ChevronDown size={12} className="text-muted-foreground shrink-0 group-hover:text-foreground transition-transform group-data-[state=open]:rotate-180" />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start" className="w-56">
              <DropdownMenuLabel className="text-xs text-muted-foreground">Switch Location</DropdownMenuLabel>
              <DropdownMenuSeparator />
              {myOrgs?.map((org) => (
                <DropdownMenuItem
                  key={org._id}
                  onClick={() => handleSwitch(org._id)}
                  className="cursor-pointer flex items-center gap-2"
                  disabled={switching === org._id}
                >
                  <div className={cn(
                    "w-5 h-5 rounded flex items-center justify-center text-[10px] font-bold shrink-0",
                    org._id === currentOrg._id ? "bg-primary/15 text-primary" : "bg-muted text-muted-foreground"
                  )}>
                    {org.name.charAt(0).toUpperCase()}
                  </div>
                  <span className="flex-1 truncate text-sm">{org.name}</span>
                  {org._id === currentOrg._id && <Check size={12} className="text-primary shrink-0" />}
                </DropdownMenuItem>
              ))}
              <DropdownMenuSeparator />
              <DropdownMenuItem
                className="cursor-pointer text-muted-foreground hover:text-foreground"
                onClick={() => navigate("/locations")}
              >
                <Plus size={12} className="mr-2" /> Add Location
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        )}
        {role && (
          <p className="text-[10px] text-muted-foreground/60 mt-0.5 capitalize">
            {role.replace("_", " ")}
          </p>
        )}
      </div>

      {/* Location filter */}
      <div className="px-3 pb-2">
        <LocationSwitcher />
      </div>

      {/* Nav */}
      <nav className="flex-1 overflow-y-auto px-3 py-4 space-y-0.5">
        {visibleItems.map(({ to, icon: Icon, label }) => {
          const badgeCount = badgeMap[to] ?? 0;
          return (
            <NavLink
              key={to}
              to={to}
              className={({ isActive }) =>
                cn(
                  "flex items-center gap-3 px-3 py-2 rounded-md text-sm font-medium transition-colors cursor-pointer",
                  isActive
                    ? "bg-primary text-primary-foreground"
                    : "text-sidebar-foreground hover:bg-sidebar-accent hover:text-sidebar-accent-foreground"
                )
              }
            >
              {({ isActive }) => (
                <>
                  <Icon size={16} />
                  <span className="flex-1">{label}</span>
                  {badgeCount > 0 && (
                    <span
                      className={cn(
                        "ml-auto inline-flex items-center justify-center rounded-full text-[10px] font-bold min-w-[18px] h-[18px] px-1",
                        isActive
                          ? "bg-primary-foreground/20 text-primary-foreground"
                          : "bg-red-500 text-white"
                      )}
                    >
                      {badgeCount > 99 ? "99+" : badgeCount}
                    </span>
                  )}
                </>
              )}
            </NavLink>
          );
        })}
      </nav>

      {/* User / Signout */}
      <div className="px-3 py-4 border-t border-sidebar-border">
        {/* Support & Legal links */}
        <div className="flex items-center gap-3 px-3 mb-2">
          <a
            href="/faq"
            onClick={(e) => { e.preventDefault(); navigate("/faq"); }}
            className="text-[11px] text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
          >
            Help & FAQ
          </a>
          <span className="text-muted-foreground/30">|</span>
          <a
            href="/contact"
            onClick={(e) => { e.preventDefault(); navigate("/contact"); }}
            className="text-[11px] text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
          >
            Support
          </a>
          <span className="text-muted-foreground/30">|</span>
          <a
            href="mailto:lee@yourcarguy806.com"
            className="text-[11px] text-muted-foreground hover:text-foreground transition-colors cursor-pointer"
          >
            Contact
          </a>
        </div>

        <div className="flex items-center gap-3 px-3 py-2 rounded-md">
          <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-primary-foreground text-sm font-bold shrink-0">
            {user?.profile.name?.[0]?.toUpperCase() ?? "U"}
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-sidebar-foreground truncate">
              {user?.profile.name ?? "User"}
            </p>
            <p className="text-xs text-muted-foreground truncate">{user?.profile.email}</p>
          </div>
        </div>
        <Button
          variant="ghost"
          size="sm"
          className="w-full justify-start gap-2 mt-1 text-muted-foreground hover:text-foreground cursor-pointer"
          onClick={handleSignout}
        >
          <LogOut size={16} />
          Sign Out
        </Button>
      </div>
    </aside>
  );
}

/**
 * Schema metadata for the Convex-compat runtime.
 *
 * Both JSON files are generated from a live Postgres instance by
 * aws/db/introspect.sql and aws/db/introspect-indexes.sql, so this can never
 * drift from aws/db/schema.sql. Regenerate them whenever the DDL changes.
 */
import columnsJson from "../db/schema.json" with { type: "json" };
import indexesJson from "../db/indexes.json" with { type: "json" };

type ColumnMeta = { type: string; nullable: boolean };
type TableMeta = Record<string, ColumnMeta>;

const COLUMNS = columnsJson as unknown as Record<string, TableMeta>;
const INDEX_COLUMNS = indexesJson as unknown as Record<string, string[]>;

export const TABLE_NAMES = Object.keys(COLUMNS);

/**
 * Identifiers are interpolated into SQL rather than parameterized, because
 * Postgres does not allow table or column names as bind parameters. Everything
 * that reaches the SQL string must therefore be checked against the real
 * schema first -- these two functions are the only sanctioned path.
 */
export function assertTable(table: string): string {
  if (!Object.prototype.hasOwnProperty.call(COLUMNS, table)) {
    throw new Error(`Unknown table: ${table}`);
  }
  return table;
}

export function assertColumn(table: string, column: string): string {
  const meta = COLUMNS[assertTable(table)];
  if (!Object.prototype.hasOwnProperty.call(meta, column)) {
    throw new Error(`Unknown column ${table}.${column}`);
  }
  return column;
}

/** Quote an identifier that has already been validated against the schema. */
export function quoteIdent(ident: string): string {
  return `"${ident.replace(/"/g, '""')}"`;
}

export function columnsOf(table: string): string[] {
  return Object.keys(COLUMNS[assertTable(table)]);
}

export function columnType(table: string, column: string): string {
  return COLUMNS[assertTable(table)][assertColumn(table, column)].type;
}

export function isJsonColumn(table: string, column: string): boolean {
  return columnType(table, column) === "jsonb";
}

/**
 * Ordered columns backing a Convex index. Convex index names are unqualified
 * ("by_org_status"); on Postgres they are prefixed with the table to keep them
 * globally unique.
 */
export function indexColumns(table: string, indexName: string): string[] {
  assertTable(table);
  const cols = INDEX_COLUMNS[`${table}_${indexName}`];
  if (!cols) {
    throw new Error(`Unknown index ${indexName} on ${table}`);
  }
  return cols;
}

export function hasIndex(table: string, indexName: string): boolean {
  return Boolean(INDEX_COLUMNS[`${table}_${indexName}`]);
}

/**
 * Convex omits optional fields that were never set, so `doc.foo` is
 * `undefined`. Postgres returns an explicit NULL for the same column. Stripping
 * nulls keeps `=== undefined` checks in the ported functions behaving as they
 * did on Convex.
 *
 * Also normalizes bigint columns, which node-postgres returns as strings.
 */
export function decodeRow<T = Record<string, unknown>>(
  table: string,
  row: Record<string, unknown> | null | undefined,
): T | null {
  if (!row) return null;
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(row)) {
    if (value === null) continue;
    if (columnType(table, key) === "bigint" && typeof value === "string") {
      out[key] = Number(value);
    } else {
      out[key] = value;
    }
  }
  return out as T;
}

/**
 * Prepare a JS value for a bind parameter. JSONB columns need serializing;
 * everything else passes through and lets node-postgres handle the encoding.
 */
export function encodeValue(table: string, column: string, value: unknown): unknown {
  if (value === undefined) return null;
  if (value !== null && isJsonColumn(table, column)) return JSON.stringify(value);
  return value;
}

import { query, mutation } from "./_generated/server";
import { v, ConvexError } from "convex/values";
import type { QueryCtx, MutationCtx } from "./_generated/server.d.ts";
import type { Doc, Id } from "./_generated/dataModel.d.ts";

async function getAuthedUser(ctx: QueryCtx | MutationCtx): Promise<Doc<"users">> {
  const identity = await ctx.auth.getUserIdentity();
  if (!identity) throw new ConvexError({ message: "Not authenticated", code: "UNAUTHENTICATED" });
  const user = await ctx.db
    .query("users")
    .withIndex("by_token", (q) => q.eq("tokenIdentifier", identity.tokenIdentifier))
    .unique();
  if (!user) throw new ConvexError({ message: "User not found", code: "NOT_FOUND" });
  return user;
}

// ─── Queries ──────────────────────────────────────────────────────────────────

/**
 * Tech's own pay records — only returns records for the currently-authed user.
 * Techs call this to see their private earnings history.
 */
export const getMyPayRecords = query({
  args: {},
  handler: async (ctx): Promise<Array<Doc<"techPayRecords">>> => {
    const user = await getAuthedUser(ctx);
    if (!user.currentOrgId) return [];

    // Find this user's member record in their current org
    const member = await ctx.db
      .query("orgMembers")
      .withIndex("by_org_user", (q) =>
        q.eq("orgId", user.currentOrgId!).eq("userId", user._id)
      )
      .first();
    if (!member) return [];

    return await ctx.db
      .query("techPayRecords")
      .withIndex("by_member_paidAt", (q) => q.eq("memberId", member._id))
      .order("desc")
      .take(200);
  },
});

/**
 * Manager view — pay records for a specific tech member.
 * Only owners/admins/service_writers should call this.
 */
export const getTechPayRecords = query({
  args: { memberId: v.id("orgMembers") },
  handler: async (ctx, args): Promise<Array<Doc<"techPayRecords">>> => {
    const user = await getAuthedUser(ctx);
    if (!user.currentOrgId) return [];

    // Verify the caller is a manager-level member of the same org
    const callerMember = await ctx.db
      .query("orgMembers")
      .withIndex("by_org_user", (q) =>
        q.eq("orgId", user.currentOrgId!).eq("userId", user._id)
      )
      .first();
    if (!callerMember) throw new ConvexError({ message: "Not a member", code: "FORBIDDEN" });
    if (!["owner", "admin", "service_writer"].includes(callerMember.role)) {
      throw new ConvexError({ message: "Insufficient permissions", code: "FORBIDDEN" });
    }

    return await ctx.db
      .query("techPayRecords")
      .withIndex("by_member_paidAt", (q) => q.eq("memberId", args.memberId))
      .order("desc")
      .take(200);
  },
});

/**
 * Org-level pay summary — total hours & earnings per tech for a date range.
 * Used in admin/manager reporting.
 */
export const getOrgPaySummary = query({
  args: {
    startDate: v.optional(v.string()), // ISO date string, inclusive
    endDate: v.optional(v.string()),   // ISO date string, inclusive
  },
  handler: async (ctx, args) => {
    const user = await getAuthedUser(ctx);
    if (!user.currentOrgId) return [];

    const callerMember = await ctx.db
      .query("orgMembers")
      .withIndex("by_org_user", (q) =>
        q.eq("orgId", user.currentOrgId!).eq("userId", user._id)
      )
      .first();
    if (!callerMember) return [];
    if (!["owner", "admin", "service_writer"].includes(callerMember.role)) return [];

    let records = await ctx.db
      .query("techPayRecords")
      .withIndex("by_org", (q) => q.eq("orgId", user.currentOrgId!))

