+export const listTemplates = query({
+  args: {},
+  handler: async (ctx) => {
+    const { orgId } = await requireOrgMember(ctx);
+    const custom = await ctx.db
+      .query("inspectionTemplates")
+      .withIndex("by_org", (q) => q.eq("orgId", orgId))
