+        priority: "normal", complaint: "Add key", isMobile: false,
+        laborLines: [], partLines: [], shopFees: [],
+        subtotal: 0, taxAmount: 0, totalAmount: 0,
+        authorizationName: "Key Customer",
+        authorizationMethod: "signature",
