import { useState } from "react";
import { useMutation, useQuery } from "convex/react";
import { api } from "@/convex/_generated/api.js";
import type { Id } from "@/convex/_generated/dataModel.d.ts";
import { Badge } from "@/components/ui/badge.tsx";
import { Button } from "@/components/ui/button.tsx";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select.tsx";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar.tsx";
import { MapPin, Clock, MoreVertical, UserMinus, DollarSign, ChevronUp, Pencil, Shield, XCircle } from "lucide-react";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger, DropdownMenuSeparator } from "@/components/ui/dropdown-menu.tsx";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog.tsx";
import { cn } from "@/lib/utils.ts";
import { toast } from "sonner";
import { formatDistanceToNow, format } from "date-fns";
import EditEmployeeDialog from "./EditEmployeeDialog.tsx";

type EmploymentType = "w2" | "1099";
type EditableRole = "admin" | "service_writer" | "mechanic" | "mobile_mechanic";
type Role = "owner" | EditableRole;

const ROLE_LABELS: Record<Role, string> = {
  owner: "Owner",
  admin: "Admin",
  service_writer: "Service Writer",
  mechanic: "Mechanic",
  mobile_mechanic: "Mobile Mechanic",
};

const ROLE_COLORS: Record<Role, string> = {
  owner: "bg-primary/20 text-primary border-primary/30",
  admin: "bg-blue-500/20 text-blue-400 border-blue-500/30",
  service_writer: "bg-purple-500/20 text-purple-400 border-purple-500/30",
  mechanic: "bg-green-500/20 text-green-400 border-green-500/30",
  mobile_mechanic: "bg-orange-500/20 text-orange-400 border-orange-500/30",
};

const EMPLOYMENT_LABELS: Record<EmploymentType, string> = {
  w2:   "W-2",
  "1099": "1099",
};

const EMPLOYMENT_COLORS: Record<EmploymentType, string> = {
  w2:   "bg-blue-500/15 text-blue-400 border-blue-500/30",
  "1099": "bg-orange-500/15 text-orange-400 border-orange-500/30",
};

function isAdminRole(role: string): boolean {
  return role === "owner" || role === "admin";
}

type Employee = {
  _id: Id<"orgMembers">;
  role: Role;
  isActive: boolean;
  inviteStatus?: "pending" | "accepted" | "declined";
  inviteEmail?: string;
  userName: string;
  userEmail?: string;
  userPhone?: string;
  avatarUrl?: string;
  employmentType?: EmploymentType;
  locationId?: Id<"locations">;
  hasAdminAccess?: boolean;
  latestPing?: {
    lat: number;
    lng: number;
    timestamp: string;
  } | null;
};

export default function EmployeeCard({
  employee,
  canEdit,
}: {
  employee: Employee;
  canEdit: boolean;
}) {

  try {
    await deleteInspection({ inspectionId: inspection._id });
    toast.success("Inspection deleted");
  } catch {
    toast.error("Failed to delete inspection");
  } finally {
    setShowDeleteConfirm(false);
  }
};

// ─── No inspection yet ───────────────────────────────────────────────────
if (!inspection) {
  return (
    <div className="flex flex-col items-center justify-center py-12 text-center px-4">
      <div className="w-14 h-14 rounded-2xl bg-primary/10 flex items-center justify-center mb-4">
        <ClipboardCheck size={24} className="text-primary" />
      </div>
      <h3 className="font-semibold mb-1">No Inspection Started</h3>
      <p className="text-sm text-muted-foreground mb-4 max-w-xs">
        Start a multi-point vehicle inspection for this RO. You can mark items OK, Needs Attention, or Critical, add notes, and attach photos.
      </p>
      <Button onClick={handleCreate} disabled={creating} className="cursor-pointer">
        {creating ? <Spinner /> : <><ClipboardCheck size={14} className="mr-1" /> Start Inspection</>}
      </Button>
    </div>
  );
}

// ─── Group items by category ─────────────────────────────────────────────
const categoryMap = new Map<string, InspectionItem[]>();
for (const item of inspection.items) {
  if (!categoryMap.has(item.category)) categoryMap.set(item.category, []);
  categoryMap.get(item.category)!.push(item);
}

return (
  <div className="space-y-4">
    {/* Header */}
    <div className="flex items-center justify-between gap-2 flex-wrap">
      <div className="flex items-center gap-2">
        <ClipboardCheck size={16} className="text-primary" />
        <span className="font-semibold text-sm">{inspection.templateName}</span>
        <Badge
          className={cn(
            "text-xs",
            inspection.status === "completed"
              ? "bg-green-500/15 text-green-400 border-green-500/30"
              : "bg-primary/15 text-primary border-primary/30"
          )}
        >
          {inspection.status === "completed" ? "Completed" : "In Progress"}
        </Badge>
      </div>
      <div className="flex gap-1">
        {inspection.status === "in_progress" && (
          <>
            <Button size="sm" variant="ghost" className="cursor-pointer text-xs" onClick={() => setShowAddItem(true)}>
              <Plus size={12} className="mr-1" /> Add Item
            </Button>
            <Button size="sm" className="cursor-pointer text-xs" onClick={() => setShowCompleteDialog(true)}>
              <CheckCircle2 size={12} className="mr-1" /> Complete
            </Button>
          </>
        )}
        <Button size="sm" variant="ghost" className="cursor-pointer text-destructive hover:text-destructive text-xs" onClick={() => setShowDeleteConfirm(true)}>
          <Trash2 size={12} />
        </Button>
      </div>
    </div>

    {/* Summary */}
    <SummaryBar items={inspection.items} />

    {/* Categories */}
    <div className="space-y-4">
      {Array.from(categoryMap.entries()).map(([cat, items]) => (
        <CategorySection key={cat} category={cat} items={items} inspectionStatus={inspection.status} />
      ))}
    </div>

